      "path": "scripts/encode_hevc_alpha.sh",
      "content": "#!/bin/zsh\n# ============================================================================\n# HEVC-with-Alpha 批量编码（sunkeycn 方案，macOS 原生 AVFoundation）\n#\n# 原理：ffmpeg 只负责把 VP9-alpha webm 解码成原始 BGRA 帧（stdin 管道），\n#       真正的 HEVC-with-Alpha 编码交给 swift 程序（AVAssetWriter +\n#       AVVideoCodecType.hevcWithAlpha）——苹果原生 API，产物由 Safari 原生\n#       验证支持（issue 贡献者已在 Safari 实测）。\n#\n# 用法：\n#   ./encode_hevc_alpha.sh [素材目录] [输出目录]\n#   默认素材 = .（兼容流水线 clone 主仓库后的 assets/webm 或 assets/thumb）\n#   默认输出 = ./dist\n#\n# 依赖（macOS runner）：\n#   - ffmpeg（解码 webm：本脚本优先用 $FFMPEG_BIN，其次 PATH 中的 ffmpeg）\n#   - xcrun + swiftc（系统自带，编译编码器）\n#   - hevc_alpha_encoder.swift（与本脚本同目录）\n#\n# 断点续跑：输出 mov 比源 webm 新则跳过（与主仓库素材链脚本同款模式）。\n# ============================================================================\n\nset -euo pipefail\n\n# ---- 参数：素材目录 / 输出目录 ----\n# 兼容两种素材布局：直接给目录，或相对 main-repo/（流水线 clone 主仓库后）\nif [[ -n \"$1\" ]]; then\n  asset_dir=$1\nelse\n  if [[ -d \"main-repo/dsh-pet/assets/webm\" ]]; then\n    asset_dir=\"main-repo/dsh-pet/assets/webm\"\n  elif [[ -d \"main-repo/dsh-pet/assets/thumb\" ]]; then\n    asset_dir=\"main-repo/dsh-pet/assets/thumb\"\n  elif [[ -d \"dsh-pet/assets/webm\" ]]; then\n    asset_dir=\"dsh-pet/assets/webm\"\n  elif [[ -d \"dsh-pet/assets/thumb\" ]]; then\n    asset_dir=\"dsh-pet/assets/thumb\"\n  else\n    print -u2 \"no asset dir found; pass it as \\$1 (e.g. main-repo/dsh-pet/assets/webm)\"\n    exit 1\n  fi\nfi\nout_dir=${2:-dist}\n\nscript_dir=${0:A:h}\nencoder_src=\"$script_dir/hevc_alpha_encoder.swift\"\nencoder_bin=$(mktemp /tmp/dsh-pet-hevc-alpha.XXXXXX)\ntemp_output=''\n\ncleanup() {\n  rm -f \"$encoder_bin\"\n  if [[ -n \"$temp_output\" ]]; then\n    rm -f \"$temp_output\"\n  fi\n}\ntrap cleanup EXIT INT TERM\n\n# ---- ffmpeg 定位 ----\nif [[ -n ${FFMPEG_BIN:-} ]]; then\n  ffmpeg_bin=$FFMPEG_BIN\nelif command -v ffmpeg >/dev/null 2>&1; then\n  ffmpeg_bin=$(command -v ffmpeg)\nelse\n  print -u2 'ffmpeg not found; install it or set FFMPEG_BIN=/absolute/path/to/ffmpeg'\n  exit 1\nfi\nif [[ ! -x \"$ffmpeg_bin\" ]]; then\n  print -u2 \"ffmpeg is not executable: $ffmpeg_bin\"\n  exit 1\nfi\n\n# ---- 编译 Swift 编码器（macOS 原生 AVFoundation + VideoToolbox）----\nxcrun swiftc -O -suppress-warnings \\\n  -framework AVFoundation \\\n  -framework CoreVideo \\\n  -framework VideoToolbox \\\n  \"$encoder_src\" \\\n  -o \"$encoder_bin\"\n\n# ---- 批量编码 ----\nmkdir -p \"$out_dir\"\nwebm_files=(\"$asset_dir\"/*.webm(N))\nif (( ${#webm_files} == 0 )); then\n  print -u2 \"no WebM assets found: $asset_dir\"\n  exit 1\nfi\n\nconverted=0\nskipped=0\nfor source_file in \"${webm_files[@]}\"; do\n  output_file=\"$out_dir/${source_file:t:r}.mov\"\n  if [[ -f \"$output_file\" && \"$output_file\" -nt \"$source_file\" ]]; then\n    (( skipped += 1 ))\n    continue\n  fi\n\n  temp_output=\"$out_dir/${source_file:t:r}.tmp.mov\"\n  rm -f \"$temp_output\"\n  print \"[$(( converted + skipped + 1))/${#webm_files}] ${source_file:t}\"\n  # ffmpeg：libvpx-vp9 解码（保留 alpha）→ 原始 BGRA 帧 → swift 编码器\n  \"$ffmpeg_bin\" \\\n    -hide_banner \\\n    -loglevel error \\\n    -c:v libvpx-vp9 \\\n    -i \"$source_file\" \\\n    -an \\\n    -f rawvideo \\\n    -pix_fmt bgra \\\n    pipe:1 \\\n    | \"$encoder_bin\" \"$temp_output\" 640 360 24\n  mv -f \"$temp_output\" \"$output_file\"\n  temp_output=''\n  (( converted += 1 ))\ndone\n\nprint \"done: converted=$converted skipped=$skipped total=${#webm_files} out=$out_dir\""
    },
    {
      "path": ".github/workflows/hevc-alpha.yml",
      "content": "# ============================================================================\n# HEVC-with-Alpha 素材流水线（与素材同仓，外层主仓库专用）\n#\n# 作用：把本仓库 dsh-pet 的透明 VP9 WebM（dsh-pet/assets/webm/*.webm）批量转成\n#       Safari 原生支持的 HEVC-with-Alpha .mov，供插件在 Safari 上透明播放。\n#\n# 设计：流水线与素材同仓——workflow 用 actions/checkout 拿到本仓库，直接对\n#       dsh-pet/assets/webm 编码，不再跨仓库 clone。产物 dsh-pet/assets/mov/\n#       就地写回插件素材目录。\n#\n# 编码方案（sunkeycn，issue 贡献者已在 Safari 实测）：\n#   ffmpeg 只负责解码（libvpx-vp9 保留 alpha）→ 原始 BGRA 帧管线 →\n#   swift hevc_alpha_encoder.swift（AVAssetWriter + hevcWithAlpha 苹果原生 API）\n#   —— 不走 ffmpeg hevc_videotoolbox 的像素格式坑，产物为 Core Media 签名。\n#\n# 触发：手动（workflow_dispatch）——素材稳定后一次性转码，避免每次 CI 都跑\n#   漫长的 macOS 编码。\n#\n# 产物：dsh-pet/assets/mov/*.mov（HEVC with Alpha, hvc1 tag），全量打包为\n#   单个 zip 并发布到 GitHub Release（macOS 用户直接从 Release 下载）。\n#\n# Release 策略：固定 tag = assets-mov（与 webm 素材 tag assets-videos 对应）。\n#   每次运行先删除旧 tag + Release，再用同名重建 → 指向最新提交，下载链接\n#   永远不变（下游/桌面端固定引用同名 Release 地址）。\n# ============================================================================\n\nname: hevc-alpha\n\non:\n  workflow_dispatch:\n\n# 发布 Release / 删除旧 tag 需要 contents: write\npermissions:\n  contents: write\n\nconcurrency:\n  group: hevc-alpha\n  cancel-in-progress: false\n\njobs:\n  encode:\n    # HEVC-with-Alpha 编码（AVFoundation hevcWithAlpha）需要 macOS\n    # 固定 macos-15：macos-14 的 arm64 runner 配置已下线（job 启动即被取消，\n    # 注解为 configuration not supported）；不同 macOS 版本的 VideoToolbox 码率\n    # 映射不同，换 runner 会改变 mov 体积，产物需重新核对\n    runs-on: macos-15\n    timeout-minutes: 120\n    steps:\n      - name: 检出本仓库（含插件素材与编码脚本）\n        uses: actions/checkout@v4\n\n      - name: 安装 ffmpeg（仅用于解码 webm，编码走原生 Swift）\n        run: |\n          brew install ffmpeg\n          ffmpeg -version | head -n 1\n\n      - name: 批量编码 HEVC-with-Alpha（Swift 原生方案）\n        run: |\n          chmod +x scripts/encode_hevc_alpha.sh\n          # 素材源：本仓库 dsh-pet/assets/webm；输出直接写回 dsh-pet/assets/mov\n          mkdir -p dsh-pet/assets/mov\n          ./scripts/encode_hevc_alpha.sh dsh-pet/assets/webm dsh-pet/assets/mov\n          echo \"mov 数量: $(ls dsh-pet/assets/mov/*.mov 2>/dev/null | wc -l)\"\n\n      - name: 校验产物（hvc1 tag + alpha 通道真实存在）\n        run: |\n          python scripts/check_alpha.py $(ls dsh-pet/assets/mov/*.mov | head -n 3)\n          for f in $(ls dsh-pet/assets/mov/*.mov | head -n 2); do\n            echo \"=== $(basename \"$f\") ===\"\n            ffprobe -v error -select_streams v:0 \\\n              -show_entries stream=codec_tag_string,codec_name,width,height \\\n              -of csv=p=0 \"$f\"\n          done\n\n      - name: 生成发布标签\n        id: release\n        run: |\n          # 固定 tag 名，与 webm 素材 tag `assets-videos` 对应\n          tag=\"assets-mov\"\n          echo \"tag=$tag\" >> \"$GITHUB_OUTPUT\"\n          echo \"release tag: $tag\"\n          # mov 数量（供 Release 正文引用）\n          echo \"count=$(ls dsh-pet/assets/mov/*.mov | wc -l | tr -d ' ')\" >> \"$GITHUB_OUTPUT\"\n\n      - name: 清理旧 tag 与 Release（同名重建）\n        run: |\n          set -euo pipefail\n          tag=\"${{ steps.release.outputs.tag }}\"\n          # 删除旧 Release（连带 tag）。不存在时 gh 报错，忽略即可。\n          gh release delete \"$tag\" --yes --cleanup-tag || true\n          # 双保险：远端 tag 若残留（gh 未清理干净）直接删除\n          git push origin \":refs/tags/$tag\" || true\n          git tag -d \"$tag\" 2>/dev/null || true\n          echo \"cleaned old release/tag: $tag\"\n\n      - name: 打包全量 zip\n        run: |\n          set -euo pipefail\n          # 输出到仓库根（$(pwd) = GITHUB_WORKSPACE）下的 dsh-pet/assets/；\n          # 用 python3 zipfile 打包（macOS 自带 zip 的退出码在中文文件名下不稳定，绕开）\n          zip_path=\"$(pwd)/dsh-pet/assets/dsh-pet-mov-${{ steps.release.outputs.tag }}.zip\"\n          python3 - \"$zip_path\" <<'EOF'\n          import sys, zipfile, glob\n          zp = sys.argv[1]\n          movs = sorted(glob.glob('dsh-pet/assets/mov/*.mov'))\n          assert movs, 'no mov files to pack'\n          with zipfile.ZipFile(zp, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as z:\n              for f in movs:\n                  z.write(f, arcname=f.rsplit('/', 1)[-1])\n          EOF\n          echo \"zip: $zip_path ($(du -h \"$zip_path\" | cut -f1))\"\n          # 校验条目：用 python zipfile 读回（避免 unzip|grep 在 pipefail 下的计数陷阱）\n          python3 - \"$zip_path\" <<'EOF'\n          import sys, zipfile\n          with zipfile.ZipFile(sys.argv[1]) as z:\n              names = z.namelist()\n          movs = [n for n in names if n.endswith('.mov')]\n          print(f'entries={len(names)} mov={len(movs)}')\n          assert movs and len(movs) == len(names), 'zip 内容异常：应全为 .mov'\n          EOF\n\n      - name: 发布到 GitHub Release\n        uses: softprops/action-gh-release@v2\n        with:\n          tag_name: ${{ steps.release.outputs.tag }}\n          name: dsh-pet macOS 素材（HEVC-alpha .mov）${{ steps.release.outputs.tag }}\n          body: |\n            macOS 桌宠透明播放素材（HEVC-with-Alpha .mov，hvc1 tag）。\n\n            - 来源：`dsh-pet/assets/webm/*.webm`（VP9-alpha，共 ${{ steps.release.outputs.count }} 个）\n            - 编码：本仓库 `scripts/encode_hevc_alpha.sh`（ffmpeg 解码 + AVFoundation hevcWithAlpha）\n            - 用途：Safari/WKWebView 不支持 WebM alpha，需用此 mov 替代\n            - 解压后文件名与 webm 一一对应，放入素材目录即可\n\n            由 hevc-alpha 流水线自动生成。固定 tag，每次运行同名重建（指向最新提交）。\n          files: ${{ github.workspace }}/dsh-pet/assets/dsh-pet-mov-${{ steps.release.outputs.tag }}.zip\n          fail_on_unmatched_files: true"
    },
    {
      "path": "scripts/check_alpha.py",
      "content": "#!/usr/bin/env python3\n\"\"\"校验 HEVC-with-Alpha 产物的 alpha 通道是否真实存在。\n\n用法：python check_alpha.py dist/*.mov（或 ls 展开）\n判断：提取首帧的 RGBA，A 通道必须有真实层次（存在 >200 的不透明像素，\n也存在 <100 的透明像素）——若全是 255 说明编码丢 alpha，必须修编码命令。\n\"\"\"\nimport os\nimport subprocess\nimport sys\n\nFFMPEG = \"ffmpeg\"\n\n\ndef check_one(path: str) -> bool:\n    rgba = path[:-4] + (\".rgba\" if not path.endswith(\".rgba\") else path)\n    r = subprocess.run(\n        [FFMPEG, \"-y\", \"-v\", \"error\", \"-i\", path, \"-ss\", \"1\", \"-frames:v\", \"1\",\n         \"-f\", \"rawvideo\", \"-pix_fmt\", \"rgba\", rgba],\n        capture_output=True, text=True,\n    )\n    if r.returncode != 0 or not os.path.exists(rgba) or os.path.getsize(rgba) < 16:\n        print(f\"  [WARN] {path}: no frame extracted\")\n        return True\n    data = open(rgba, \"rb\").read()\n    alpha = data[3::4]  # rgba 每像素 4 字节，A 是第 4 个\n    a_min, a_max = min(alpha), max(alpha)\n    a_mean = sum(alpha) / len(alpha)\n    ok = a_max > 200 and a_min < 100\n    print(f\"  alpha min={a_min} max={a_max} mean={a_mean:.1f} -> {'OK' if ok else '!! LOST'}\")\n    os.remove(rgba)\n    return ok\n\n\ndef main() -> int:\n    files = sys.argv[1:]\n    if not files:\n        print(\"usage: python check_alpha.py <mov...> 或 ls dist/*.mov | xargs python check_alpha.py\")\n        return 2\n    failed = 0\n    for f in files:\n        if not check_one(f):\n            failed += 1\n    print(f\"check: {len(files) - failed}/{len(files)} alpha OK\")\n    return 1 if failed else 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"
    },
    {
      "path": ".gitignore",
      "content": "# ── 素材处理链中间产物（跑 scripts/*.py 可再生，不入仓库） ──\nstep01/\nstep02/\nstep03/\nstep04/\n\n# ── 素材源（托管在 GitHub Releases assets-videos，不入仓库） ──\nvideo/*.mp4\n\n# ── PR 手工抠像工作数据（本地工作数据，同 step 中间产物，不入库） ──\n#   pr/      PR 导出的透明 .mov（路线 B 的输入）\n#   prproj/  PR 工程目录（.prproj + 遮罩缓存 + 自动保存，约 2GB）\npr/\nprproj/\n\n# ── 本地工具（机器相关，不入仓库） ──\n.tools/\n\n# ── Python ──\n__pycache__/\n*.py[cod]\n.venv/\n.uv-cache/\n\n# ── Node ──\nnode_modules/\n.npm-cache/\n.npm-tmp-cache/\nnpm-debug.log*\n*.tgz\n\n# ── 临时/备份目录 ──\ntemp/\n\n# ── dsh-pet 构建产物（全部由 src/ 构建生成，不入仓库；克隆后先 npm run prepare:webm）──\n#   lib/                      tsdown bundle（lib/index.js、lib/client.js）+ tsc 声明（lib/types/*.d.ts，npm run types）\n#   runtime/electron-helper/shared-core.js  桌面共享纯逻辑（scripts/build-desktop-core.mjs 产出，window.PetShared）\n# （lib/types 曾是手写声明才保留跟踪；自 gen-types.mjs 起为生成产物，与 lib/*.js 同等对待）\ndsh-pet/lib/\ndsh-pet/runtime/electron-helper/shared-core.js\n\n# ── dsh-pet 桌宠应用打包产物（electron-builder 输出，`node scripts/dist.mjs` 可重生）──\ndsh-pet/dist-app/\n\n# ── IDE / 编辑器 ──\n.idea/\n.vscode/\n*.swp\n\n# ── 系统文件 ──\n.DS_Store\nThumbs.db\ndesktop.ini\n"
    },
    {
      "path": "scripts/watermark_step01.py",
      "content": "\"\"\"水印填充（step01）：video/*.mp4 → step01/*.mp4（水印像素用第5近背景色填充）\n\n素材处理链第 1 步（替代原 crop_step01 的职责——去水印，且更精确）：\n  video/（1280x720 原视频）→ 本脚本 → step01/（水印去除后的 1280x720）\n  → chroma_step02.py（绿幕抠像）→ normalize_step03.py → encode_thumbs.py\n\n方案（已验证）：\n- mask：video/watermark_mask_v5.mkv（黑视频亮度>10 生成，覆盖淡入淡出水印）\n- 取色：每个水印像素取第 5 近的\"非水印像素\"颜色（跳过紧贴的未标记水印字空洞）\n- 输出：libx264 crf18 yuv420p，与原视频同尺寸/帧率，供 chromakey 抠像\n\n并发：PARALLEL 个视频同时处理（每视频独立 Python 进程 + 3 个 ffmpeg 子进程）。\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport subprocess\nimport sys\nfrom concurrent.futures import ProcessPoolExecutor\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nSRC = ROOT / \"video\"\nOUT = ROOT / \"step01\"\nMASK = SRC / \"watermark_mask_v5.mkv\"\nK = 5\nPARALLEL = 4\n# 统一使用工作区自带的 ffmpeg（素材处理链零第三方依赖）\nFFMPEG = str(ROOT / \".tools\" / \"ffmpeg-9.0.1-essentials_build\" / \"bin\" / \"ffmpeg.exe\")\nFFPROBE = str(ROOT / \".tools\" / \"ffmpeg-9.0.1-essentials_build\" / \"bin\" / \"ffprobe.exe\")\nsys.path.insert(0, str(ROOT / \"scripts\"))\nfrom fill_nn import fill_nn  # noqa: E402\n\n\ndef duration(video: Path) -> int:\n    r = subprocess.run([FFMPEG, \"-i\", str(video), \"-f\", \"null\", \"-\"],\n                       capture_output=True, text=True, errors=\"replace\")\n    m = re.findall(r\"Duration:\\s*(\\d+):(\\d+):(\\d+)\\.(\\d+)\", r.stderr)\n    if not m:\n        return 10\n    h, mi, s, cs = map(int, m[0])\n    return max(1, h * 3600 + mi * 60 + s + (1 if cs else 0))\n\n\ndef _is_valid(dst: Path, src: Path, min_size: int = 50_000) -> bool:\n    \"\"\"断点续跑完整性检查：存在、够大、不比源旧、且能被 ffprobe 读到视频流。\n\n    ffprobe 验证防止\"中断时正在写、大小看似足够但已损坏\"的文件被误判为已完成。\n    \"\"\"\n    if not dst.exists() or dst.stat().st_size <= min_size:\n        return False\n    if dst.stat().st_mtime < src.stat().st_mtime:\n        return False\n    r = subprocess.run([FFPROBE, \"-v\", \"error\", \"-show_entries\", \"stream=codec_name\",\n                        \"-of\", \"csv=p=0\", str(dst)], capture_output=True)\n    return bool(r.stdout.strip())\n\n\ndef _process_one(video: Path) -> tuple[str, str]:\n    \"\"\"处理单个视频（worker 函数，必须模块级以支持 Windows spawn）。\"\"\"\n    dst = OUT / video.name\n    if _is_valid(dst, video):\n        return video.name, \"SKIP\"\n    rc = fill_nn(video, MASK, dst, duration(video), K)\n    return video.name, \"OK\" if rc == 0 else f\"FAIL rc={rc}\"\n\n\ndef main() -> int:\n    OUT.mkdir(exist_ok=True)\n    videos = sorted(SRC.glob(\"*.mp4\"))\n    if not videos:\n        print(f\"No MP4 files found in {SRC}\")\n        return 1\n    if not MASK.exists():\n        print(f\"Missing mask: {MASK}\")\n        return 1\n\n    total = len(videos)\n    with ProcessPoolExecutor(max_workers=PARALLEL) as ex:\n        for index, (name, status) in enumerate(ex.map(_process_one, videos), start=1):\n            print(f\"[{index}/{total}] {name} {status}\", flush=True)\n\n    print(f\"Done. {total} videos written to {OUT} (parallel={PARALLEL})\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"
    }
